// CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;

const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};

  headers.forEach((h, i) => {
    obj[h] = cols[i] ?? "";
  });

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const clientes = $json.body?.clientes || [];
const investimentos = $json.investimentos || [];

const resultado = [];

for (const cliente of clientes) {

  // Encontra investimentos compatíveis com o perfil do cliente
  const recomendados = investimentos.filter(
    investimento => investimento.perfil === cliente.perfil
  );

  // Monta a lista de investimentos
  const listaInvestimentos = recomendados
    .map(inv => {
      return `• ${inv.produto} — mínimo: R$ ${inv.minimo} — rentabilidade: ${inv.rentabilidade}`;
    })
    .join('\n');


  // =====================================================
  // OPÇÃO 1 — MENSAGEM PROFISSIONAL
  // =====================================================

  const mensagem1 = `
Olá, ${cliente.nome}!

Identificamos algumas opções de investimento compatíveis com o seu perfil de investidor: ${cliente.perfil}.

Considerando seu saldo atual de ${cliente.saldo}, apresentamos abaixo as opções disponíveis para esse perfil:

${listaInvestimentos}

Essas informações são apresentadas exclusivamente para fins informativos e não constituem recomendação financeira.

Atenciosamente,
Equipe de Investimentos
  `.trim();


  // =====================================================
  // OPÇÃO 2 — MENSAGEM CONSULTIVA
  // =====================================================

  const mensagem2 = `
Olá, ${cliente.nome}! Tudo bem?

Analisamos seu perfil de investidor, classificado como ${cliente.perfil}, e encontramos algumas opções de investimento que podem ser consideradas dentro desse perfil.

Seu saldo informado atualmente é de ${cliente.saldo}.

Confira algumas das opções encontradas:

${listaInvestimentos}

Antes de realizar qualquer investimento, avalie seus objetivos, prazo e tolerância a riscos.

Estas informações são apenas informativas e não constituem recomendação financeira.

Um abraço,
Equipe de Investimentos
  `.trim();


  // =====================================================
  // OPÇÃO 3 — MENSAGEM DIRETA
  // =====================================================

  const mensagem3 = `
Olá, ${cliente.nome}!

Seu perfil é ${cliente.perfil} e seu saldo atual é de ${cliente.saldo}.

Encontramos estas opções compatíveis com seu perfil:

${listaInvestimentos}

Consulte as condições e avalie os riscos antes de investir.

Informações apenas para fins informativos, não constituindo recomendação financeira.

Equipe de Investimentos
  `.trim();


  // =====================================================
  // RESULTADO
  // =====================================================

  resultado.push({
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,

      investimentos_recomendados: recomendados,

      assunto: `Opções de investimento para ${cliente.nome}`,

      // As três opções ficam disponíveis
      mensagem_1: mensagem1,
      mensagem_2: mensagem2,
      mensagem_3: mensagem3,

      // Mensagem padrão que será usada inicialmente
      mensagem: mensagem1
    }
  });
}

return resultado;

// Recebe todos os clientes vindos do Code in JavaScript1
const entradas = $input.all();


// =====================================================
// CONVERTER VALOR EM REAIS PARA NÚMERO
// Exemplo:
// "R$ 12.500,00" -> 12500
// "R$ 3.200,00"  -> 3200
// =====================================================

function parseBRL(valor) {
  if (!valor) return 0;

  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.-]/g, "")
    .trim();

  const n = Number(s);

  return Number.isFinite(n) ? n : 0;
}


// =====================================================
// PROCESSAR CADA CLIENTE
// =====================================================

const out = entradas.map(item => {

  const c = item.json;


  // Saldo
  const saldoTexto = c.saldo ?? "";

  const saldoNum =
    c.saldo_num ?? parseBRL(saldoTexto);


  // Investimentos encontrados
  const investimentos =
    Array.isArray(c.investimentos_recomendados)
      ? c.investimentos_recomendados
      : [];


  // ===================================================
  // TRÊS MENSAGENS
  // ===================================================

  const mensagem1 = c.mensagem_1 ?? "";
  const mensagem2 = c.mensagem_2 ?? "";
  const mensagem3 = c.mensagem_3 ?? "";


  // ===================================================
  // ESCOLHER UMA DAS 3 MENSAGENS
  // ===================================================

  const mensagens = [
    mensagem1,
    mensagem2,
    mensagem3
  ].filter(Boolean);


  const mensagemEscolhida =
    mensagens.length > 0
      ? mensagens[Math.floor(Math.random() * mensagens.length)]
      : "";


  // ===================================================
  // RETORNAR CLIENTE
  // ===================================================

  return {
    json: {

      // Dados do cliente
      nome: c.nome ?? "",
      email: c.email ?? "",
      perfil: c.perfil ?? "",

      // Saldo
      saldo_texto: saldoTexto,
      saldo_num: saldoNum,

      // Investimentos
      investimentos_recomendados: investimentos,

      quantidade_investimentos: investimentos.length,

      // Assunto
      assunto:
        c.assunto ??
        `Opções de investimento para ${c.nome ?? "cliente"}`,

      // As três opções
      mensagem_1: mensagem1,
      mensagem_2: mensagem2,
      mensagem_3: mensagem3,

      // Mensagem escolhida aleatoriamente
      mensagem_escolhida: mensagemEscolhida,

      // Mantém também a mensagem original
      mensagem: c.mensagem ?? mensagemEscolhida
    }
  };
});


return out;

